using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BNApply {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B2/",P=A+"Props/B2/";
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_DomeNetwork/";static string O=>R+"/Docs/Review/2026-11-10_B2_DomeNetwork/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");return s;}
 static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);
 static GameObject Group(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 public static object Import(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);Directory.CreateDirectory(O);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(m=>m.name.StartsWith("BCM_")).ToDictionary(m=>"B4O_"+m.name.Substring(4));mats["B2M_Plate"]=mats["B4O_Plate"];foreach(string n in new[]{"Pipe","PipeRed"})mats["BM_"+n]=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BM_"+n+".mat");int count=0;foreach(var p in Directory.GetFiles(E,"BN_*.fbx").Concat(Directory.GetFiles(P,"BN_*.fbx")).Select(p=>p.Replace('\\','/'))){var mi=(ModelImporter)AssetImporter.GetAtPath(p);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();count++;}AssetDatabase.SaveAssets();return new{models=count};}
 static GameObject Put(string n,string asset,Transform parent,bool solid=false,bool hidden=false,bool lod=true){var src=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(!src)throw new Exception("Missing "+asset);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=n;g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;var original=g.GetComponentsInChildren<MeshRenderer>();foreach(var f in g.GetComponentsInChildren<MeshFilter>()){if(solid)f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;if(hidden)f.GetComponent<MeshRenderer>().enabled=false;}if(lod&&!hidden){var far=AssetDatabase.LoadAssetAtPath<GameObject>(asset.Replace(".fbx","_LOD1.fbx"));if(far){var low=(GameObject)PrefabUtility.InstantiatePrefab(far,g.transform);low.name="Distance_LOD1";low.transform.localPosition=Vector3.zero;low.transform.localRotation=Quaternion.identity;var group=g.AddComponent<LODGroup>();group.fadeMode=LODFadeMode.CrossFade;group.SetLODs(new[]{new LOD(.12f,original.Cast<Renderer>().ToArray()),new LOD(0,low.GetComponentsInChildren<Renderer>())});group.RecalculateBounds();if(asset.Contains("UpperWalk"))group.size=16;}}return g;}
 static void Save(Scene s){foreach(var t in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}
 public static object Run(){var s=Check();var net=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork").transform;if(net.Find("B2_DomeServiceNetwork"))throw new Exception("Already applied; use targeted repairs");var data=JObject.Parse(File.ReadAllText(H+"layout.json"));var original=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_FullFloor/layout.json"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();foreach(var m in JObject.Parse(File.ReadAllText(H+"models.json")).Properties()){string asset=A+(string)m.Value["category"]+"/B2/"+m.Name+".fbx";if(!AssetDatabase.LoadAssetAtPath<GameObject>(asset))throw new Exception("Missing generated asset "+asset);}var root=Group("B2_DomeServiceNetwork",net).transform;try{
 var halls=Group("ConnectedUpperRoutes",root).transform;foreach(var t in data["tunnels"]){string id=(string)t["id"];net.Find("B2_DetailPass/UpperServiceRoutes/B2_"+id+"_CrouchPassage").gameObject.SetActive(false);var g=Group("B2_"+id+"_DomeConnectedRoute",halls).transform;Put("B2_"+id+"_ThroughGrating",E+"BN_"+id+"_UpperWalk.fbx",g);Put("B2_"+id+"_ThroughWalkCollision",E+"BN_"+id+"_UpperWalk_Collision.fbx",g,true,true,false);Put("B2_"+id+"_DomeHeader",E+"BN_"+id+"_HeaderContinuation.fbx",g,true);}
 var domes=Group("DomeMezzanines",root).transform;foreach(var d in ((JObject)data["decks"]).Properties()){string id=d.Name;var r=data["rooms"].Single(v=>(string)v["id"]==id);var g=Group("B2_"+id+"_ServiceMezzanine",domes).transform;g.localPosition=new Vector3((float)r["x"],0,-(float)r["v"]);Put("B2_"+id+"_RingGratingAndStair",E+"BN_"+id+"_ServiceDeck.fbx",g);Put("B2_"+id+"_RingWalkCollision",E+"BN_"+id+"_ServiceDeck_Collision.fbx",g,true,true,false);Put("B2_"+id+"_OverheadDistribution",E+"BN_"+id+"_OverheadPlant.fbx",g,true);
 for(int i=0;i<3;i++){var pendant=all.Single(v=>v.name=="B2_"+id+"_Pendant_"+i);var suspension=all.Single(v=>v.name==pendant.name+"_Suspension");var pos=pendant.localPosition;float oldY=pos.y;pos.y=6.3f;pendant.localPosition=pos;suspension.localPosition+=Vector3.up*(6.3f-oldY);var scale=suspension.localScale;scale.y-=6.3f-oldY;suspension.localScale=scale;}}
 var c02=s.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector").transform;var c=Group("B2_C02_UpperTunnelConnection",domes).transform;c.position=c02.position;Put("B2_C02_T01_Connector",E+"BN_C02_Connector.fbx",c);Put("B2_C02_T01_ConnectorCollision",E+"BN_C02_Connector_Collision.fbx",c,true,true,false);all.Single(t=>t.name=="B2_C02_MezzanineGuards").gameObject.SetActive(false);Put("B2_C02_OpenedMezzanineGuards",E+"BN_C02_OpenedGuards.fbx",c,true);
 var equipment=Group("ProcessIslandsAndMaintenance",root).transform;int count=0;foreach(var p in data["placements"]){string id=(string)p["room"];var r=data["rooms"].Single(v=>(string)v["id"]==id);var room=equipment.Find("B2_"+id+"_ProcessIsland");if(!room){room=Group("B2_"+id+"_ProcessIsland",equipment).transform;room.localPosition=new Vector3((float)r["x"],0,-(float)r["v"]);}string model=(string)p["model"];var prototype=original["placements"].FirstOrDefault(v=>(string)v["model"]==model);GameObject g;if(prototype!=null){var src=all.Single(t=>t.name==(string)prototype["name"]);g=UnityEngine.Object.Instantiate(src.gameObject,room);g.name=(string)p["name"];}else{g=Put((string)p["name"],(string)p["asset"],room);var col=g.AddComponent<BoxCollider>();col.center=V(p["center"]);col.size=V(p["size"]);}g.transform.localPosition=V(p["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);count++;}
 foreach(var camera in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))camera.useOcclusionCulling=false;
 Save(s);var result=new{equipment=count,newMezzanines=3,connectedDomes=4,connectedTunnels=6,upperJunctions=7,activeLights=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).Count()};Directory.CreateDirectory(O);File.WriteAllText(O+"apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }catch{EditorSceneManager.OpenScene(s.path);throw;}}
}
